import * as T from './vendor/three.module.js';
export {T};
const metal=new T.MeshStandardMaterial({color:0x2c4251,metalness:.72,roughness:.48});
const dark=new T.MeshStandardMaterial({color:0x101f2e,metalness:.6,roughness:.5});
const edge=new T.MeshStandardMaterial({color:0x587181,metalness:.7,roughness:.32});
