const mint=new T.MeshStandardMaterial({color:0x74eecf,emissive:0x56e9c6,emissiveIntensity:2.2});
const orange=new T.MeshStandardMaterial({color:0xf49562,emissive:0xff7043,emissiveIntensity:1.5});
const blue=new T.MeshStandardMaterial({color:0x76bdff,emissive:0x2d8ee6,emissiveIntensity:1.9});
const red=new T.MeshStandardMaterial({color:0xff563b,emissive:0xff3322,emissiveIntensity:2.8});
function box(parent,w,h,d,x,y,z,mat=metal){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.receiveShadow=true;m.castShadow=true;parent.add(m);return m;}
function cyl(parent,r1,r2,h,x,y,z,mat=metal,segments=12){const m=new T.Mesh(new T.CylinderGeometry(r1,r2,h,segments),mat);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
function label(parent,text,x,y,z,width=3,color='#abc5d2',size=70){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=color;ctx.font=`500 ${size}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,512,128);const map=new T.CanvasTexture(c);map.colorSpace=T.SRGBColorSpace;const mesh=new T.Mesh(new T.PlaneGeometry(width,width/4),new T.MeshBasicMaterial({map,transparent:true,depthWrite:false}));mesh.position.set(x,y,z);parent.add(mesh);return mesh;}
function torus(parent,r,t,x,y,z,mat=metal){const o=new T.Mesh(new T.TorusGeometry(r,t,8,48),mat);o.position.set(x,y,z);parent.add(o);return o;}
export function createWorld(canvas){
const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;
const scene=new T.Scene();scene.background=new T.Color(0x050d19);scene.fog=new T.FogExp2(0x091827,.012);
const camera=new T.PerspectiveCamera(49,innerWidth/innerHeight,.1,260);camera.position.set(-6,10,18);
scene.add(new T.HemisphereLight(0xb2dcf9,0x142836,2.1));const sun=new T.DirectionalLight(0xc1e9ff,2.8);sun.position.set(-5,18,9);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-22;sun.shadow.camera.right=22;sun.shadow.camera.top=18;sun.shadow.camera.bottom=-18;sun.shadow.bias=-.0005;scene.add(sun);scene.add(sun.target);
const positions=new Float32Array(2500*3);let seed=32;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}for(let i=0;i<2500;i++){positions[i*3]=(rnd()-.35)*340;positions[i*3+1]=(rnd()-.4)*180;positions[i*3+2]=-30-rnd()*140;}const starGeo=new T.BufferGeometry();starGeo.setAttribute('position',new T.BufferAttribute(positions,3));const stars=new T.Points(starGeo,new T.PointsMaterial({color:0xb4d7ee,size:.14,transparent:true,opacity:.85,sizeAttenuation:true}));scene.add(stars);
const planetMat=new T.ShaderMaterial({vertexShader:`varying vec3 vN;varying vec3 vP;void main(){vN=normalize(normalMatrix*normal);vP=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,fragmentShader:`varying vec3 vN;varying vec3 vP;void main(){float light=max(0.,dot(normalize(vN),normalize(vec3(-.7,.7,.8))));float stripes=sin(vP.y*.18+sin(vP.x*.2)*.6+sin(vP.z*.2));vec3 c=mix(vec3(.024,.075,.15),vec3(.12,.4,.59),light);c+=vec3(.1,.15,.18)*smoothstep(.3,.85,stripes)*light;float rim=pow(1.-max(dot(normalize(vN),vec3(0,0,1)),0.),3.);c+=vec3(.13,.36,.53)*rim;gl_FragColor=vec4(c,1.);}`});const planet=new T.Mesh(new T.SphereGeometry(35,64,48),planetMat);planet.position.set(31,-18,-86);scene.add(planet);
const moon=new T.Mesh(new T.SphereGeometry(4,24,24),new T.MeshStandardMaterial({color:0x7597a3,roughness:1}));moon.position.set(-23,24,-85);scene.add(moon);
const ship=new T.Group();scene.add(ship);const floors=[[ -8,14],[21,76],[88,114]];const obstacles=[];const hazards=[];const animated=[];
// A cutaway hull keeps both gravity surfaces and the route readable.
for(let x=-7;x<114;x+=2){const floorExists=floors.some(([a,b])=>x>=a&&x+1.8<=b);if(floorExists){box(ship,1.91,.28,8,x+.95,-.16,0,floorMat);for(const z of[-3.7,3.7])box(ship,1.55,.015,.06,x+.95,.006,z,edge);for(const z of[-2.8,2.8]){box(ship,.08,.02,.33,x+.28,.012,z,dark);box(ship,.08,.02,.33,x+1.62,.012,z,dark);}if(Math.floor(x)%6===1){for(let n=0;n<5;n++)box(ship,.6,.015,.025,x+.95,.015,-.3+n*.14,dark);}}box(ship,1.97,.2,1.4,x+.95,8.55,-3.55,metal);box(ship,1.97,.13,.65,x+.95,8.55,3.68,metal);box(ship,1.97,.12,.06,x+.95,8.48,1.9,mint);box(ship,1.97,.12,.06,x+.95,8.48,-1.9,mint);if(floorExists){box(ship,1.4,.025,.07,x+.95,.02,-3.25,blue);box(ship,1.4,.025,.07,x+.95,.02,3.25,blue);}}
for(let x=-8;x<114;x+=7){box(ship,.25,8.8,.32,x,4.25,-4.3,edge);box(ship,.23,.35,8.7,x,8.65,0,edge);box(ship,.45,.42,8.8,x,-.35,0,dark);box(ship,6.7,1.5,.25,x+3.5,.75,-4.35,dark);box(ship,6.7,.65,.25,x+3.5,8,-4.35,dark);box(ship,6.7,.12,.15,x+3.5,1.55,-4.15,edge);box(ship,6.7,.12,.15,x+3.5,7.6,-4.15,edge);box(ship,6.5,.035,.05,x+3.5,7.2,-4.1,blue);box(ship,.1,5.6,.12,x+3.5,4.4,-4.3,metal);const glass=new T.Mesh(new T.PlaneGeometry(6.7,5.8),new T.MeshPhysicalMaterial({color:0x3d829a,transparent:true,opacity:.08,metalness:.2,roughness:.2,side:T.DoubleSide,depthWrite:false}));glass.position.set(x+3.5,4.5,-4.37);ship.add(glass);for(let z=-2.9;z<3;z+=1.45)box(ship,.28,.42,.35,x,8.36,z,metal);cyl(ship,.075,.075,6.5,x+3.5,7.93,-3.87,dark).rotation.z=Math.PI/2;}
// Intact ceiling collision surface is marked with suspended guide rails.
for(const z of[-3.1,3.1]){box(ship,122,.1,.12,53,8.5,z,edge);box(ship,122,.08,.14,53,-.55,z,edge);}
for(const [a,b] of[[14,21],[76,88]]){for(const x of[a-.3,b+.3]){box(ship,.55,.1,8,x,.035,0,dark);for(let z=-3.6;z<3.8;z+=.65){const stripe=box(ship,.44,.025,.3,x,.1,z,orange);stripe.rotation.y=.5;}}for(let n=0;n<8;n++){const debris=box(ship,.5+rnd(),.18,.4+rnd(),a+rnd()*(b-a),-1.7-rnd()*3,(rnd()-.5)*7,dark);debris.rotation.set(rnd()*3,rnd()*3,rnd()*3);animated.push({type:'debris',mesh:debris,base:debris.position.clone(),phase:rnd()*6});}}
// Starting platform signage, consoles and physical cargo.
label(ship,'ODYSSEY  /  079',3,6.15,-4.12,5,'#8caabb',62);label(ship,'HABITAT',8,2.4,-4.09,3,'#90b5c5',55);label(ship,'01',-2,4.4,-4.09,2.2,'#8effd9',100);label(ship,'MIND THE GAP',13,1.9,-4.08,3.1,'#ffab70',48);label(ship,'GRAVITY TRANSIT',21,7,-4.09,4,'#8effd9',52);
function cargo(x,z,w=1.6,h=1.2){const g=new T.Group();g.position.set(x,h/2,z);ship.add(g);box(g,w,h,1.4,0,0,0,metal);for(const s of[-1,1]){box(g,.08,h+.04,1.43,s*w*.34,0,0,edge);box(g,w+.05,.06,1.46,0,s*h*.33,0,edge);}box(g,.25,.12,.03,0,.1,.72,orange);obstacles.push({x,z,w,h,y:0,d:1.4});return g;}
cargo(7,-2.6);cargo(10,-2.9,1.6,1.6);cargo(27,2.8,2,1.2);cargo(40,-2.7,2,1.1);cargo(60,2.6,1.6,1.5);cargo(72,-2.7,1.8,1.2);cargo(100,2.8,1.6,1.1);
for(const x of[0,32,38,67,72,101]){box(ship,1.9,1.3,.7,x,.65,-3.5,dark);const monitor=box(ship,1.65,.8,.07,x,1.45,-3.1,new T.MeshStandardMaterial({color:0x164c58,emissive:0x0d3b4a,emissiveIntensity:.7}));monitor.rotation.x=-.18;for(let i=0;i<5;i++)box(ship,.2+(i%3)*.3,.018,.012,x-.55+i*.08,1.7-i*.12,-3.046,mint);}
const gates=[];for(const [index,x]of[35,70].entries()){const g=new T.Group();g.position.x=x;ship.add(g);for(const z of[-4,4])box(g,.7,8.5,.5,0,4.25,z,edge);box(g,.7,.5,8,0,8.2,0,edge);const panel=box(g,.32,7.8,7.5,0,3.9,0,new T.MeshStandardMaterial({color:0x173b47,metalness:.7,roughness:.45,transparent:true,opacity:.77}));for(const z of[-3.4,3.4])box(panel,.35,6.7,.1,0,0,z,orange);label(ship,`BULKHEAD 0${index+1}`,x-2.1,6.9,-4.05,3,'#ffbd87',48);gates.push({x,mesh:panel,open:false,amount:0});}
function laser(x,y,phase){const g=new T.Group();g.position.set(x,y,0);ship.add(g);const beams=[];for(let h=-.7;h<=.8;h+=.5){const b=box(g,.12,.06,7.7,0,h,0,red);beams.push(b);}for(const z of[-3.9,3.9])box(g,.5,2.2,.28,0,0,z,metal);const aura=box(g,.07,2,7.7,0,0,0,new T.MeshBasicMaterial({color:0xff503b,transparent:true,opacity:.05,depthWrite:false}));const item={x,y,phase,mesh:g,beams,aura,active:true};hazards.push(item);return item;}
laser(45,1.2,0);laser(54,7.25,2.6);laser(62,4.25,1.3);label(ship,'02  /  MAINTENANCE',47,5.8,-4.1,5,'#90b5c5',52);label(ship,'CAUTION  /  LASER ARRAY',55,3,-4.1,4,'#ff9e76',42);
// Exposed reactor, rotating rings, arcing pit and shielded core.
label(ship,'03  /  REACTOR',81,6.8,-4.1,4.3,'#fbb38d',55);
const reactor=new T.Group();reactor.position.set(83,3.8,-5.5);ship.add(reactor);cyl(reactor,1.35,1.35,6.5,0,0,0,dark,24);cyl(reactor,.7,.7,5.6,0,0,0,new T.MeshStandardMaterial({color:0x48adbc,emissive:0x298dad,emissiveIntensity:2.5}),24);for(let y=-2.4;y<3;y+=1.2){const ring=torus(reactor,1.75,.09,0,y,0,edge);ring.rotation.x=Math.PI/2;animated.push({type:'ring',mesh:ring});}const reactLight=new T.PointLight(0x57bfea,35,20,2);reactLight.position.set(83,3,-2);scene.add(reactLight);
const arc=new T.Group();arc.position.set(82,0,0);ship.add(arc);for(let i=0;i<14;i++){const m=box(arc,.05,2.8,.05,-5+rnd()*10,-1,rnd()*7-3.5,blue);m.rotation.z=(rnd()-.5)*.9;animated.push({type:'arc',mesh:m,phase:rnd()*10});}
const cores=[];for(const [i,p]of[[28,7.4,0],[65,1.15,-1.1],[96,1.15,0]].entries()){const g=new T.Group();g.position.set(...p);ship.add(g);const shape=new T.Mesh(new T.OctahedronGeometry(.48),mint);g.add(shape);const r1=torus(g,.74,.025,0,0,0,mint);r1.rotation.y=.8;const r2=torus(g,.62,.022,0,0,0,edge);r2.rotation.x=1.3;const light=new T.PointLight(0x64f9d0,4,6);g.add(light);const base=p[1]>4?8.42:.1;box(ship,1.2,.15,1.2,p[0],base,p[2],dark);box(ship,.78,.04,.78,p[0],base+(p[1]>4?-.1:.1),p[2],mint);cores.push({index:i,x:p[0],y:p[1],z:p[2],mesh:g,collected:false,shape,r1,r2});}
const shield=new T.Mesh(new T.CylinderGeometry(1.1,1.1,2.7,24,1,true),new T.MeshBasicMaterial({color:0xff704a,transparent:true,opacity:.25,wireframe:true}));shield.position.set(96,1.4,0);ship.add(shield);
const switchObj={x:92,y:7.35,z:-1.5,active:false};const sw=new T.Group();sw.position.set(switchObj.x,switchObj.y,switchObj.z);ship.add(sw);box(sw,.9,.7,.4,0,0,0,metal);const swLight=box(sw,.6,.35,.05,0,0,.23,orange);label(ship,'SHIELD OVERRIDE',92,6.45,-3.9,3,'#ffad7d',48);switchObj.mesh=sw;switchObj.light=swLight;
const supplies=[];for(const [x,y,z,type]of[[11,1,1.7,'oxygen'],[30,1,-2,'health'],[38,1,1.7,'oxygen'],[57,7.4,1.8,'oxygen'],[73,1,.5,'health'],[90,7.4,1.8,'oxygen'],[102,1,-1.5,'oxygen']]){const g=new T.Group();g.position.set(x,y,z);ship.add(g);const mat=type==='oxygen'?blue:mint;cyl(g,.22,.22,.66,0,0,0,edge);cyl(g,.225,.225,.25,0,0,0,mat);cyl(g,.12,.12,.13,0,.4,0,dark);supplies.push({x,y,z,type,mesh:g,taken:false});}
const logs=[];for(const [i,p]of[[9,1.2,2.7],[51,7.3,-2.6],[99,1.2,-2.7]].entries()){const g=new T.Group();g.position.set(...p);ship.add(g);const screen=box(g,.5,.7,.08,0,0,0,blue);screen.rotation.z=.15;logs.push({x:p[0],y:p[1],z:p[2],index:i,mesh:g,taken:false});}
const pod=new T.Group();pod.position.set(108,0,0);ship.add(pod);const shellMat=new T.MeshStandardMaterial({color:0x9cadb4,metalness:.6,roughness:.3});const capsule=new T.Mesh(new T.CapsuleGeometry(1.75,3,8,24),shellMat);capsule.position.y=3;pod.add(capsule);box(pod,2.2,3,.35,-.08,2.45,1.48,dark);box(pod,1.65,1.6,.18,-.08,3.15,1.69,new T.MeshStandardMaterial({color:0x164350,emissive:0x236781,metalness:.9,roughness:.2}));for(let x=-1;x<=1;x+=2){box(pod,.08,2.85,.12,x,2.5,1.75,mint);cyl(pod,.4,.65,.8,x,.6,0,dark);}label(pod,'ESCAPE  07',0,4.48,1.5,2,'#163941',68);label(ship,'EXTRACTION POINT',104,6.5,-4.05,5,'#9cf3da',52);
const dustGeo=new T.BufferGeometry();const dustPos=new Float32Array(220*3);for(let i=0;i<220;i++){dustPos[i*3]=rnd()*120-8;dustPos[i*3+1]=rnd()*9;dustPos[i*3+2]=(rnd()-.5)*8;}dustGeo.setAttribute('position',new T.BufferAttribute(dustPos,3));const dust=new T.Points(dustGeo,new T.PointsMaterial({color:0x91b4c8,size:.035,transparent:true,opacity:.55}));scene.add(dust);
const player=createAstronaut();scene.add(player.group);
function update(t,dt,px){sun.position.x=px-8;sun.target.position.set(px+5,0,0);for(const a of animated){if(a.type==='debris'){a.mesh.rotation.x+=dt*.08;a.mesh.rotation.z+=dt*.06;a.mesh.position.y=a.base.y+Math.sin(t*.5+a.phase)*.15;}if(a.type==='ring')a.mesh.rotation.z=t*.4;if(a.type==='arc')a.mesh.visible=Math.sin(t*12+a.phase)>.15;}for(const c of cores){c.shape.rotation.y=t*.7;c.r1.rotation.x=t*.9;c.r2.rotation.y=-t*.6;c.mesh.position.y=c.y+Math.sin(t*1.9+c.index)*.12;}for(const s of supplies){s.mesh.rotation.y=t*.7;s.mesh.position.y=s.y+Math.sin(t*2+s.x)*.1;}for(const l of logs)l.mesh.rotation.y=Math.sin(t*.8)*.3;for(const h of hazards){const phase=(t+h.phase)%5.8;h.active=phase<2.6;const warning=phase>5.1;for(const b of h.beams)b.visible=h.active||(warning&&Math.sin(t*25)>0);h.aura.visible=h.active;}for(const g of gates){g.amount=T.MathUtils.damp(g.amount,g.open?1:0,3,dt);g.mesh.position.y=3.9+g.amount*8;}shield.rotation.y=t*.3;dust.rotation.x=Math.sin(t*.025)*.006;}
return {renderer,scene,camera,player,floors,obstacles,hazards,cores,supplies,logs,gates,shield,switchObj,pod,update,resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}};
}
function createAstronaut(){const group=new T.Group();const pivot=new T.Group();group.add(pivot);const body=new T.Group();pivot.add(body);const suit=new T.MeshStandardMaterial({color:0xe2e8df,metalness:.25,roughness:.45});const joint=new T.MeshStandardMaterial({color:0x223744,metalness:.35,roughness:.6});const trim=new T.MeshStandardMaterial({color:0xe59e5e,metalness:.5,roughness:.38});box(body,.7,.72,.46,0,.1,0,suit);box(body,.53,.5,.18,0,.12,-.35,edge);box(body,.34,.3,.07,0,.18,.26,joint);box(body,.13,.04,.02,-.07,.24,.305,mint);box(body,.07,.05,.02,.08,.15,.305,orange);box(body,.72,.1,.48,0,-.18,0,trim);const helmet=new T.Mesh(new T.SphereGeometry(.39,24,18),suit);helmet.scale.set(1,1,1.03);helmet.position.y=.68;body.add(helmet);const visor=new T.Mesh(new T.SphereGeometry(.343,24,12,0,Math.PI*2,0,Math.PI),new T.MeshPhysicalMaterial({color:0x122e40,metalness:1,roughness:.13,clearcoat:1}));visor.scale.set(1,.68,.57);visor.position.set(0,.7,.23);body.add(visor);box(body,.19,.035,.015,-.09,.82,.422,new T.MeshBasicMaterial({color:0x9ed8ec}));for(const x of[-.34,.34]){cyl(body,.11,.11,.08,x,.64,0,edge).rotation.z=Math.PI/2;}const limbs=[];for(const s of[-1,1]){const leg=new T.Group();leg.position.set(s*.21,-.3,0);body.add(leg);box(leg,.28,.42,.31,0,-.2,0,suit);box(leg,.29,.12,.33,0,-.4,0,joint);box(leg,.27,.28,.31,0,-.57,0,suit);box(leg,.32,.15,.46,0,-.76,.06,joint);const arm=new T.Group();arm.position.set(s*.47,.36,0);body.add(arm);box(arm,.25,.32,.28,0,-.13,0,suit);box(arm,.27,.1,.3,0,-.29,0,trim);box(arm,.22,.27,.25,0,-.45,.02,suit);box(arm,.23,.15,.25,0,-.62,.03,joint);limbs.push({leg,arm,s});cyl(body,.11,.11,.56,s*.2,.08,-.43,blue);}
const flame=new T.Mesh(new T.ConeGeometry(.12,.7,10),new T.MeshBasicMaterial({color:0x76e7fa,transparent:true,opacity:.7}));flame.rotation.x=Math.PI;flame.position.set(0,-.45,-.37);body.add(flame);flame.visible=false;group.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});return{group,pivot,body,limbs,flame};}
